+    private JvmVendorSpec mapBundledJdkVendorToVendorSpec(String bundledJdkVendor) {
+        return bundledJdkVendor.equals("openjdk") ? JvmVendorSpec.ORACLE : JvmVendorSpec.matching(bundledJdkVendor);
+    }
